(function(){const dlg=document.getElementById("ce-formula-dialog");const body=dlg.querySelector("#ce-bands-body");const renumber=()=>Array.from(body.rows).forEach((row,i)=>row.querySelectorAll("input").forEach((input,j)=>input.name=(j===0?"ce_threshold[":j===1?"ce_points[":"condition_color[")+i+"]"));const add=dlg.querySelector("#ce-add"),remove=dlg.querySelector("#ce-remove"),sort=dlg.querySelector("#ce-sort");if(add)add.onclick=()=>{if(body.rows.length>=40)return;const row=body.rows[body.rows.length-1].cloneNode(true);row.cells[0].querySelector("input").value=Number(row.cells[0].querySelector("input").value)+1;row.cells[1].querySelector("input").value=0;body.appendChild(row);renumber()};if(remove)remove.onclick=()=>{if(body.rows.length>1)body.deleteRow(-1);renumber()};if(sort)sort.onclick=()=>{Array.from(body.rows).sort((a,b)=>Number(a.cells[0].querySelector("input").value)-Number(b.cells[0].querySelector("input").value)).forEach(row=>body.appendChild(row));renumber()};const form=dlg.querySelector("form");if(form)form.addEventListener("submit",renumber)})();
